// Screen wake lock utility — prevents screen sleep during audio sessions.
//
// Uses the proven NoSleep.js technique: a real base64-encoded mp4 video file
// played on loop in a hidden video element. Mobile browsers treat this as
// active media playback and keep the screen on.
//
// CRITICAL: video.play() must be called synchronously in the user gesture
// context (button click). Any preceding await will burn the gesture allowance
// and cause play() to be rejected on mobile.

import { browser } from '$app/environment';

// NoSleep.js silent mp4 (MIT licensed, from github.com/nicholasgillespie/nosleep-ts)
const SILENT_MP4 = 'data:video/mp4;base64,';

let wakeLockSentinel: any = null;
let videoEl: HTMLVideoElement | null = null;
let enabled = false;
let healthCheckId: ReturnType<typeof setInterval> | null = null;

async function tryWakeLock(): Promise<void> {
	if (wakeLockSentinel) return;
	try {
		if ('wakeLock' in navigator) {
			wakeLockSentinel = await (navigator as any).wakeLock.request('screen');
			wakeLockSentinel?.addEventListener('release', () => { wakeLockSentinel = null; });
		}
	} catch {}
}

function onVisibilityChange(): void {
	if (!enabled || document.hidden) return;
	tryWakeLock();
	if (videoEl?.paused) videoEl.play().catch(() => {});
}

function healthCheck(): void {
	if (!enabled) return;
	tryWakeLock();
	if (videoEl?.paused) videoEl.play().catch(() => {});
}

/**
 * MUST be called synchronously from a user gesture handler (button click).
 * The video.play() call is the FIRST thing that happens — no awaits before it.
 * Any preceding async operation would burn the user gesture allowance on mobile.
 */
export function enableScreenWake(): void {
	if (!browser || enabled) return;
	enabled = true;

	// FIRST: play the NoSleep video — must be synchronous in user gesture
	if (!videoEl) {
		videoEl = document.createElement('video');
		videoEl.setAttribute('playsinline', '');
		videoEl.setAttribute('title', 'Screen Wake');
		videoEl.src = SILENT_MP4;
		videoEl.loop = true;
		videoEl.style.cssText =
			'position:fixed;bottom:0;right:0;width:1px;height:1px;opacity:0.01;pointer-events:none;z-index:9999';
		document.body.appendChild(videoEl);
	}
	// This MUST be the first async call in the gesture — no awaits before it
	videoEl.play().catch(() => {});

	// THEN: wake lock as additional layer (async, fine to be after play)
	tryWakeLock();

	// Health check: re-acquire and restart every 15s
	healthCheckId = setInterval(healthCheck, 15000);
	document.addEventListener('visibilitychange', onVisibilityChange);
}

export function disableScreenWake(): void {
	if (!browser) return;
	enabled = false;

	document.removeEventListener('visibilitychange', onVisibilityChange);
	if (healthCheckId) { clearInterval(healthCheckId); healthCheckId = null; }
	try { wakeLockSentinel?.release(); } catch {}
	wakeLockSentinel = null;

	if (videoEl) {
		videoEl.pause();
		videoEl.src = '';
		videoEl.remove();
		videoEl = null;
	}
}
